#include "layer_art.h"
#include "layer_art_count.h"

/* Generated by tools/gen_art.py; holds only the artwork for the configured
 * panel rotation. */
extern const lv_image_dsc_t *const keeb_art[KBEEB_ART_COUNT];

const lv_image_dsc_t *keeb_layer_art(uint8_t layer) {
	if (KBEEB_ART_COUNT == 0) {
		return NULL;
	}

	if (layer >= KBEEB_ART_COUNT) {
		layer = KBEEB_ART_COUNT - 1;
	}

	return keeb_art[layer];
}
